two_sum.brute:
for each index i:
    for each index j after i:
        if nums[i] + nums[j] == target:
            return [i, j]
return []

majority_element.brute:
for each value in nums:
    occurrences = 0
    for each other in nums:
        if other == value: occurrences += 1
    if occurrences > n / 2:
        return value
return -1

valid_sudoku.brute:
for each cell (row, col) on the board:
    digit = board[row][col]
    if digit is '.': skip
    for each k from 0 to 8:
        if k != col and board[row][k] == digit: return False   (same row)
        if k != row and board[k][col] == digit: return False   (same column)
    (box_row, box_col) = top-left corner of the 3x3 box holding (row, col)
    for each cell (i, j) in that box:
        if (i, j) != (row, col) and board[i][j] == digit: return False
return True

group_anagrams.brute:
groups = empty list
for each word in strs:
    placed = False
    for each group in groups:
        if sorted letters of group's first word == sorted letters of word:
            add word to group, placed = True, break
    if not placed:
        start a new group [word]
return groups

top_k_frequent_elements.optimal:
freq = count of each value in nums
buckets = n + 1 empty lists   (buckets[c] holds the values that appear exactly c times)
for each value in freq:
    append value to buckets[freq[value]]
result = empty list
for count from n down to 1:
    for each value in buckets[count]:
        append value to result
        if size of result == k:
            return result
return result

product_of_array_except_self.brute:
answer = empty list
for each index i:
    product = 1
    for each index j:
        if j != i:
            product = product * nums[j]
    append product to answer
return answer

longest_consecutive_sequence.optimal:
values = set of nums
best = 0
for each start in values:
    if start - 1 is in values:
        skip start   (not the start of a run; the run is counted from its true start)
    length = 1
    while start + length is in values:
        length += 1
    best = max(best, length)
return best

subarray_sum_equals_k.brute:
answer = 0
for each start index:
    running = 0
    for each end from start to n - 1:
        running += nums[end]
        if running == k:
            answer += 1
return answer

move_zeroes.brute:
moved = True
while moved:   (one bubble pass per round, until a pass moves nothing)
    moved = False
    for each i from 0 to n - 2:
        if nums[i] == 0 and nums[i + 1] != 0:
            swap nums[i] and nums[i + 1]
            moved = True

move_zeroes.optimal:
write = 0   (next slot for a non-zero)
for each read from 0 to n - 1:
    if nums[read] != 0:
        swap nums[write] and nums[read]   (the zero at write moves forward to read)
        write += 1

sort_colors.optimal:
low = 0, mid = 0, high = n - 1   (0s before low, 1s from low to mid, 2s after high)
while mid <= high:
    if nums[mid] == 0:
        swap nums[low] and nums[mid]
        low += 1, mid += 1
    else if nums[mid] == 1:
        mid += 1
    else:
        swap nums[mid] and nums[high]
        high -= 1   (mid stays: the value swapped in has not been examined yet)

two_sum_ii_input_array_is_sorted.brute:
for each index i:
    for each index j after i:
        if numbers[i] + numbers[j] == target:
            return [i + 1, j + 1]   (1-based indices)
return []

two_sum_ii_input_array_is_sorted.optimal:
left = 0, right = n - 1
while left < right:
    total = numbers[left] + numbers[right]
    if total == target: return [left + 1, right + 1]   (1-based indices)
    if total < target: left += 1   (too small: only a bigger left value can raise the sum)
    else: right -= 1   (too big: only a smaller right value can lower it)
return []

three_sum.brute:
found = empty set
for each triple of indices i < j < k:
    if nums[i] + nums[j] + nums[k] == 0:
        add the sorted triple (nums[i], nums[j], nums[k]) to found   (sorted so clones match)
return found as a list of lists

three_sum.optimal:
sort nums, result = empty list
for each i from 0 to n - 3:
    if nums[i] > 0: stop   (everything after is positive too)
    if i > 0 and nums[i] == nums[i - 1]: skip this i   (same anchor gives the same triplets)
    left = i + 1, right = n - 1
    while left < right:
        total = nums[i] + nums[left] + nums[right]
        if total < 0: left += 1
        else if total > 0: right -= 1
        else:
            append [nums[i], nums[left], nums[right]] to result
            left += 1, right -= 1
            step left over repeats of nums[left - 1], step right over repeats of nums[right + 1]
return result
